    "  ELSE ARRAY[]::text[] END;\n"
    " FOREACH key IN ARRAY keys LOOP\n"
    "  IF payload->>key IS NOT NULL THEN "
    "links=array_append(links,(payload->>key)::uuid); "
    "END IF;\n"
    " END LOOP;\n"
    " -- Publication's exact saved read set is a "
